function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5000);}
function feedback(message,speak=false){$('feedback').textContent=message;if(speak&&$('voice').checked&&'speechSynthesis'in window&&performance.now()-lastSpeak>6500){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(message);u.rate=.95;u.voice=speechSynthesis.getVoices().find(v=>v.name===$('voice-select').value)||null;speechSynthesis.speak(u);lastSpeak=performance.now();}}
function voices(){if(!('speechSynthesis'in window)){$('voice').disabled=true;return;}const selected=$('voice-select').value;const list=speechSynthesis.getVoices().filter(v=>v.lang.startsWith('en'));$('voice-select').replaceChildren(new Option('System default',''));list.forEach(v=>$('voice-select').add(new Option(v.name,v.name)));const preferred=list.find(v=>/David|Mark|Daniel|George|James|Male/i.test(v.name));$('voice-select').value=selected||(preferred?.name||'');}voices();if('speechSynthesis'in window)speechSynthesis.onvoiceschanged=voices;
function setExercise(key){if(mode||busy){toast('Finish the current session before changing exercise.');return;}exercise=key;counter=new RepCounter(key);document.querySelectorAll('[data-exercise]').forEach(b=>b.classList.toggle('selected',b.dataset.exercise===key));$('exercise-type').textContent=EXERCISES[key].type;$('joint-label').textContent=EXERCISES[key].joint;$('form-tips').replaceChildren(...EXERCISES[key].tips.map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));$('camera-hint').textContent=key==='curl'?'Side view · Arm fully visible · Good lighting':'Side view · Full body visible · Good lighting';feedback(EXERCISES[key].setup);renderMetrics();}
function target(){return Math.max(1,Math.min(100,Number($('target').value)||10));}function setTarget(n){$('target').value=Math.max(1,Math.min(100,n));renderMetrics();}
function renderMetrics(conf=null){$('reps').textContent=counter.reps;$('phase').textContent=counter.phase;$('target-display').textContent='/ '+target();$('rep-progress').style.width=Math.min(100,counter.reps/target()*100)+'%';if(conf!==null){$('confidence').textContent=Math.round(conf*100);$('confidence-note').textContent=conf>=.65?'Required joints visible':'Improve camera framing';}}
function timeText(ms){const s=Math.floor(ms/1000);return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}
function begin(source){$('camera-help').hidden=true;mode=source;paused=false;counter=new RepCounter(exercise);elapsed=0;demoTime=0;samples=[];confidenceSum=0;confidenceN=0;started=Date.now();lastTick=performance.now();lastSample=0;$('camera-empty').hidden=true;$('angle-chip').hidden=false;$('pause').disabled=false;$('pause').textContent='Pause';$('finish').disabled=false;$('session-status').textContent=source==='demo'?'Guided demo':'Live session';$('camera-status').textContent=source==='demo'?'SIMULATED DEMO':'LIVE CAMERA';$('camera-status').classList.add('live');$('source-label').textContent=source==='demo'?'SYNTHETIC POSE · NO CAMERA':'MEDIAPIPE POSE';document.body.classList.add('running');feedback(source==='demo'?'This guided demo uses simulated landmarks to demonstrate the same angle and repetition rules used by the camera.':EXERCISES[exercise].setup,true);$('target').disabled=true;$('target-minus').disabled=true;$('target-plus').disabled=true;renderMetrics();}
async function enableCamera(){if(busy||mode)return;busy=true;$('start-camera').disabled=true;$('start-demo').disabled=true;$('start-camera').textContent='Loading pose model…';try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Camera requires localhost or HTTPS. Open the app using Start Exercise Intelligence.cmd.');if(!model){const {FilesetResolver,PoseLandmarker}=await import('./vendor/vision_bundle.mjs');const files=await FilesetResolver.forVisionTasks('./vendor/wasm');model=await PoseLandmarker.createFromOptions(files,{baseOptions:{modelAssetPath:'./vendor/pose_landmarker_lite.task',delegate:'CPU'},runningMode:'VIDEO',numPoses:1,minPoseDetectionConfidence:.6,minPosePresenceConfidence:.6,minTrackingConfidence:.6});}$('start-camera').textContent='Allow camera access…';stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:960},height:{ideal:600},facingMode:'user'},audio:false});video.srcObject=stream;await video.play();lastFrame=-1;begin('camera');}catch(err){stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;const message=err.name==='NotAllowedError'?'Camera permission was denied. Allow camera access in your browser, or use the guided demo.':err.name==='NotFoundError'?'No camera found. Connect a webcam, or use the guided demo.':err.name==='NotReadableError'?'Your camera is busy. Close other camera apps and try again.':err.message?.includes('localhost')?err.message:'Could not start pose tracking. Reload and try again, or use the guided demo.';$('camera-help').hidden=false;feedback(message);toast(message);}finally{busy=false;$('start-camera').disabled=false;$('start-demo').disabled=false;$('start-camera').textContent='◉ Enable camera';}}
function stop(save=true){if(!mode)return;const source=mode;if(save){history.unshift({id:crypto.randomUUID(),date:new Date(started).toISOString(),exercise,source,reps:counter.reps,target:target(),duration:Math.round(elapsed/1000),confidence:confidenceN?Math.round(confidenceSum/confidenceN*100):null});try{localStorage.setItem('fitvision.sessions.v1',JSON.stringify(history));toast('Session saved to workout history.');}catch{toast('Session is available now, but browser storage is full. Export your history.');}}mode=null;paused=false;stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;ctx.clearRect(0,0,canvas.width,canvas.height);$('camera-empty').hidden=false;$('angle-chip').hidden=true;$('camera-status').textContent='CAMERA OFF';$('camera-status').classList.remove('live');$('source-label').textContent='POSE ANALYSIS';$('tracking-status').textContent='Session complete';$('pause').disabled=true;$('pause').textContent='Pause';$('finish').disabled=true;$('target').disabled=false;$('target-minus').disabled=false;$('target-plus').disabled=false;$('session-status').textContent='Session saved';document.body.classList.remove('running');if('speechSynthesis'in window)speechSynthesis.cancel();feedback(`${source==='demo'?'Demo':'Workout'} complete. ${counter.reps} repetitions in ${timeText(elapsed)}. Your session is in workout history.`);}
function pause(){if(!mode)return;paused=!paused;counter.resetCycle();$('pause').textContent=paused?'Resume':'Pause';$('session-status').textContent=paused?'Paused':mode==='demo'?'Guided demo':'Live session';$('tracking-status').textContent=paused?'Paused · return to start position when resuming':'Find the extended start position';document.body.classList.toggle('running',!paused);if('speechSynthesis'in window)speechSynthesis.cancel();renderMetrics();}
function processPose(points,now){const cfg=EXERCISES[exercise];if(!points){counter.update(NaN,0,now);$('tracking-status').textContent='No pose detected · move into frame';$('angle-live').textContent='—';renderMetrics(0);feedback('Move into the frame and keep the required joints visible.',true);return;}
const score=ids=>Math.min(...ids.map(i=>{const p=points[i];return p&&p.x>.015&&p.x<.985&&p.y>.015&&p.y<.985?(p.visibility??0):0;}));let ids=score(cfg.indices)>=score(cfg.other)?cfg.indices:cfg.other;let needed=ids;if(exercise==='pushup')needed=[...ids,ids[0]===11?23:24,ids[0]===11?27:28];const conf=score(needed);const scaled=points.map(p=>({...p,x:p.x*(mode==='camera'?video.videoWidth:960),y:p.y*(mode==='camera'?video.videoHeight:600)}));const deg=angle(...ids.map(i=>scaled[i]));const counted=counter.update(deg,conf,now);drawPose(points,conf,ids);renderMetrics(conf);$('angle-live').textContent=conf>=.65?Math.round(deg)+'°':'—';$('tracking-status').textContent=conf>=.65?(mode==='demo'?'Simulated landmarks':'Pose tracked')+' · '+counter.phase:'Tracking paused · improve framing';if(conf<.65){feedback('Keep the required joints inside the frame. Counting is paused until tracking improves.',true);return;}confidenceSum+=conf;confidenceN++;if(now-lastSample>80){samples.push({t:elapsed,a:deg});samples=samples.filter(s=>elapsed-s.t<15000);lastSample=now;}
if(counted){feedback(counter.reps===target()?`Target reached. ${counter.reps} complete repetitions. Finish the session to save your workout.`:`Rep ${counter.reps} complete. Keep the next movement controlled.`,true);}
else if(exercise==='squat'){feedback(counter.stage==='seek'?'Stand tall to begin. Keep a side view so the knee angle can reach 150°.':counter.stage==='top'?`Start position found. Bend comfortably below 115°. Current knee angle: ${Math.round(deg)}°.`:`Bend detected. Stand tall above 150° to complete the rep. Current knee angle: ${Math.round(deg)}°.`);}
else if(exercise==='pushup'){const hip=ids[0]===11?23:24,ankle=ids[0]===11?27:28;const body=angle(scaled[ids[0]],scaled[hip],scaled[ankle]);if(body<150)feedback('Try to keep your shoulders, hips and ankles in a straighter line.',true);}
else if(exercise==='curl'){const shoulder=scaled[ids[0]],elbow=scaled[ids[1]];if(Math.abs(elbow.x-shoulder.x)>Math.abs(elbow.y-shoulder.y)*.65)feedback('Keep your upper arm closer to your torso as you curl.',true);}}
function drawPose(points,conf,ids){ctx.clearRect(0,0,960,600);const vw=mode==='camera'?video.videoWidth:960,vh=mode==='camera'?video.videoHeight:600;const scale=Math.min(960/vw,600/vh),ox=(960-vw*scale)/2,oy=(600-vh*scale)/2;const xy=p=>[ox+(mode==='camera'?1-p.x:p.x)*vw*scale,oy+p.y*vh*scale];ctx.lineWidth=3;ctx.strokeStyle=conf>=.65?'#91dcb9':'#e9b768';ctx.shadowColor='#96ffc0';ctx.shadowBlur=6;connections.forEach(([a,b])=>{if((points[a]?.visibility||0)<.5||(points[b]?.visibility||0)<.5)return;ctx.beginPath();ctx.moveTo(...xy(points[a]));ctx.lineTo(...xy(points[b]));ctx.stroke();});points.forEach((p,i)=>{if((p.visibility||0)<.5||i<11)return;ctx.beginPath();ctx.arc(...xy(p),ids.includes(i)?7:4,0,2*Math.PI);ctx.fillStyle=ids.includes(i)?'#c3ff7f':'#d2ede1';ctx.fill();});ctx.shadowBlur=0;if(mode==='demo'){ctx.fillStyle='#829f91';ctx.font='12px sans-serif';ctx.textAlign='center';ctx.fillText('GUIDED MOVEMENT SIMULATION',480,515);}}
function simulated(t){const theta=(170-(1-Math.cos(t/4200*2*Math.PI))*.5*(exercise==='curl'?135:95))*Math.PI/180;const p=Array.from({length:33},()=>({x:.5,y:.5,z:0,visibility:0}));const set=(i,x,y)=>p[i]={x:x/960,y:y/600,z:0,visibility:.98};
if(exercise==='squat'){const knee=[500,345],hip=[500+105*Math.sin(theta),345+105*Math.cos(theta)];set(23,...hip);set(25,...knee);set(27,500,455);set(11,hip[0]-18,hip[1]-120);set(13,hip[0]-65,hip[1]-63);set(15,hip[0]-110,hip[1]-98);set(31,460,463);for(const [a,b]of [[11,12],[13,14],[15,16],[23,24],[25,26],[27,28],[31,32]])p[b]={...p[a],x:p[a].x+.035};}
else if(exercise==='curl'){set(11,470,175);set(13,470,280);set(15,470-100*Math.sin(theta),280-100*Math.cos(theta));set(23,465,335);set(25,460,410);set(27,460,470);set(31,420,475);for(const [a,b]of [[11,12],[13,14],[15,16],[23,24],[25,26],[27,28],[31,32]])p[b]={...p[a],x:p[a].x+.04};}
else{const elbow=[390,345],shoulder=[390+100*Math.sin(theta),345+100*Math.cos(theta)];set(11,...shoulder);set(13,...elbow);set(15,390,455);set(23,shoulder[0]+145,shoulder[1]+65);set(25,shoulder[0]+230,shoulder[1]+100);set(27,shoulder[0]+325,shoulder[1]+145);set(31,shoulder[0]+340,shoulder[1]+145);for(const[a,b]of [[11,12],[13,14],[15,16],[23,24],[25,26],[27,28],[31,32]])p[b]={...p[a],y:p[a].y+.02};}return p;}
function drawChart(){cx.clearRect(0,0,850,100);cx.strokeStyle='#2b3630';cx.lineWidth=1;for(let y=20;y<100;y+=30){cx.beginPath();cx.moveTo(0,y);cx.lineTo(850,y);cx.stroke();}if(samples.length<2)return;cx.strokeStyle='#b5f469';cx.lineWidth=2;cx.beginPath();samples.forEach((s,i)=>{const x=850-(elapsed-s.t)/15000*850,y=90-s.a/180*75;i?cx.lineTo(x,y):cx.moveTo(x,y);});cx.stroke();}
function tick(now){const dt=Math.min(100,now-lastTick);lastTick=now;if(mode&&!paused){elapsed+=dt;$('timer').textContent=timeText(elapsed);try{if(mode==='demo'){demoTime+=dt;processPose(simulated(demoTime),now);}else if(video.readyState>=2&&lastFrame!==video.currentTime){lastFrame=video.currentTime;const result=model.detectForVideo(video,now);processPose(result.landmarks[0],now);}}catch{pause();feedback('Tracking was interrupted. Finish this session and restart the camera.');}drawChart();}requestAnimationFrame(tick);}requestAnimationFrame(tick);
function view(name){document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==name+'-view');document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('page-title').replaceChildren(document.createTextNode({coach:'Live coach',history:'Workout history',about:'Project overview'}[name]));const dot=document.createElement('span');dot.className='accent';dot.textContent='.';$('page-title').append(dot);if(name!=='coach'&&mode&&!paused)pause();if(name==='history')renderHistory();}
function renderHistory(){const live=history.filter(s=>s.source==='camera');$('history-summary').replaceChildren(...[[live.length,'Live sessions'],[live.reduce((n,s)=>n+s.reps,0),'Live repetitions'],[history.filter(s=>s.source==='demo').length,'Demo sessions']].map(([n,label])=>{const a=document.createElement('article'),b=document.createElement('strong'),s=document.createElement('span');b.textContent=n;s.textContent=label;a.append(b,s);return a;}));$('history-empty').hidden=history.length>0;$('history-body').replaceChildren(...history.map(s=>{const tr=document.createElement('tr');[new Date(s.date).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}),EXERCISES[s.exercise]?.name||s.exercise,`${s.reps} / ${s.target}`,timeText(s.duration*1000),s.source==='demo'?'Simulated demo':'Live camera'].forEach((t,i)=>{const td=document.createElement('td');td.textContent=t;if(i===4&&s.source==='demo')td.className='demo-label';tr.append(td);});return tr;}));$('export').disabled=!history.length;}
function exportCSV(){const rows=[['Date','Exercise','Reps','Target','Duration seconds','Source','Mean landmark confidence %'],...history.map(s=>[s.date,EXERCISES[s.exercise]?.name,s.reps,s.target,s.duration,s.source,s.confidence??''])];const blob=new Blob([rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='exercise-intelligence-workouts.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.querySelectorAll('[data-exercise]').forEach(b=>b.onclick=()=>setExercise(b.dataset.exercise));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$('project-button').onclick=()=>view('about');$('back-coach').onclick=()=>view('coach');$('start-camera').onclick=enableCamera;$('start-demo').onclick=()=>{if(!mode&&!busy)begin('demo');};$('pause').onclick=pause;$('finish').onclick=()=>stop();$('target-minus').onclick=()=>setTarget(target()-1);$('target-plus').onclick=()=>setTarget(target()+1);$('target').onchange=()=>setTarget(target());$('export').onclick=exportCSV;document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>feedback(b.dataset.prompt==='setup'?EXERCISES[exercise].setup:`Begin extended above ${EXERCISES[exercise].up} degrees, bend below ${EXERCISES[exercise].down} degrees, then return. Both endpoints must be stable. Incomplete cycles do not count.`,true));$('voice').onchange=()=>{if($('voice').checked){lastSpeak=-Infinity;feedback('Atlas voice coaching is on. '+EXERCISES[exercise].setup,true);}else if('speechSynthesis'in window)speechSynthesis.cancel();};document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode&&!paused)pause();});window.addEventListener('beforeunload',()=>stream?.getTracks().forEach(t=>t.stop()));setExercise('squat');drawChart();
